// Validation (from the original WF-01) + builds the request body the FastAPI backend expects.
const body = $input.first().json.body ?? $input.first().json;

const destination = String(body.destination ?? "").trim();
const startDate = body.startDate ?? body.start_date;
const endDate = body.endDate ?? body.end_date;
const budget = Number(body.budget);
const travelers = Number(body.travelers ?? 1);
const interests = Array.isArray(body.interests) ? body.interests : [];
const origin = body.origin ? String(body.origin).trim() : null;
const travelStyle = body.travelStyle ?? body.travel_style ?? "balanced";

const errors = [];

if (!destination) {
  errors.push("Destination is required");
}

if (!startDate || !endDate) {
  errors.push("Start date and end date are required");
} else {
  const start = new Date(startDate);
  const end = new Date(endDate);

  if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime())) {
    errors.push("Invalid travel dates");
  } else if (end < start) {
    errors.push("End date must be on or after the start date");
  }
}

if (!Number.isFinite(budget) || budget <= 0) {
  errors.push("Budget must be greater than zero");
}

if (!Number.isInteger(travelers) || travelers < 1 || travelers > 50) {
  errors.push("Travelers must be between 1 and 50");
}

if (errors.length > 0) {
  return [{ json: { success: false, statusCode: 400, errors } }];
}

return [{
  json: {
    success: true,
    statusCode: 200,
    tripRequest: { destination, startDate, endDate, budget, currency: "INR", travelers, interests },
    // Body for POST /api/trips/generate (the backend re-validates everything).
    payload: {
      destination,
      origin,
      start_date: startDate,
      end_date: endDate,
      budget,
      travelers,
      interests,
      travel_style: travelStyle,
    },
    message: "Trip request validated successfully",
  },
}];
